INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-058', '비스(2-에틸헥실)아디페이트', 'Bis-2-ethylhexyl Adipate', 'DEHA', '㎎/L', '유해물질', '물환경보전법 시행규칙 별표 13', '제34조', '2019-01-01', '개정 2025. 3. 20.', 'statutory', TRUE, '물환경보전법 시행규칙 별표 3 제32호(비스(2-에틸헥실)아디페이트)', 'https://www.law.go.kr/법령/물환경보전법시행규칙', 'verified', NULL, '초안 누락분');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-059', '안티몬', 'Antimony', 'Sb', '㎎/L', '중금속', '물환경보전법 시행규칙 별표 13', '제34조', '2019-01-01', '개정 2025. 3. 20.', 'statutory', TRUE, '물환경보전법 시행규칙 별표 3 제33호(안티몬)', 'https://www.law.go.kr/법령/물환경보전법시행규칙', 'verified', NULL, '초안 누락분');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-047', '주석', 'Tin', 'Sn', '㎎/L', '중금속', '물환경보전법 시행규칙 별표 13', '제34조', '2021-01-01', '개정 2025. 3. 20.', 'statutory', FALSE, '별표 3 목록에 없음', 'https://www.law.go.kr/법령/물환경보전법시행규칙', 'verified', NULL, NULL);
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-042', '폼산', 'Formic Acid', '-', '㎎/L', '유해물질', NULL, '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', NULL, NULL, NULL, 'rejected', NULL, '초안(AI 생성)에 있었으나 별표 13 전체(19쪽) 어디에도 없음. 근거 확인 전까지 사용 금지. 코드는 재사용 방지를 위해 남겨 둔다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-060', '용존산소량', 'Dissolved Oxygen', 'DO', '㎎/L', '일반', '환경정책기본법 시행령 별표 1 환경기준(제2조 관련) — 하천 생활환경 기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '배출허용기준 항목은 아니지만 하천 환경기준의 정식 항목이자 하천 데이터의 핵심 컬럼');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-061', '클로로필-a', 'Chlorophyll-a', 'Chl-a', '㎎/㎥', '일반', '환경정책기본법 시행령 별표 1 환경기준(제2조 관련) — 호소 생활환경 기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '하천 기준에는 없고 ''호소'' 기준에만 있는 항목. 법령 단위는 ㎎/㎥이나 데이터는 ㎎/L로 오는 경우가 있어 값 해석 시 1000배 차이 주의');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-062', '전기전도도', 'Electrical Conductivity', 'EC', 'μS/㎝', '일반', '공공데이터 공통표준용어(ELCD)', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'draft', NULL, '환경정책기본법 시행령 별표 1 전문 검색 결과 0건 — 환경기준 항목이 아님. 공통표준용어에는 ''전기전도도 ELCD''로 등재. 측정 근거는 수질오염공정시험기준에서 재확인 필요');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-063', '분원성대장균군', 'Fecal Coliforms', 'FC', '군수/100mL', '미생물', '환경정책기본법 시행령 별표 1 환경기준(제2조 관련) — 하천 생활환경 기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '환경기준 단위는 군수/100mL. 별표 13의 총대장균군은 군수/㎖ — 단위 기준이 서로 다르다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-064', '암모니아성 질소', 'Ammonia Nitrogen', 'NH3-N', '㎎/L', '영양염류', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1(제2조 관련) 제2호 아목', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '기준 0.5㎎/L. 법령 표기에 공백이 있다(''암모니아성 질소'')');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-065', '질산성 질소', 'Nitrate Nitrogen', 'NO3-N', '㎎/L', '영양염류', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1(제2조 관련) 제2호 자목', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '기준 10㎎/L. 법령 표기에 공백이 있다(''질산성 질소'')');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-066', '인산염 인', 'Phosphate Phosphorus', 'PO4-P', '㎎/L', '영양염류', '수질오염공정시험기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'draft', NULL, NULL);
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-067', '용존총질소', 'Dissolved Total Nitrogen', 'DTN', '㎎/L', '영양염류', '수질오염공정시험기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'draft', NULL, NULL);
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-068', '용존총인', 'Dissolved Total Phosphorus', 'DTP', '㎎/L', '영양염류', '수질오염공정시험기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'draft', NULL, NULL);
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-069', '탁도', 'Turbidity', 'NTU', 'NTU', '일반', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1(제2조 관련) 제5호 파목', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '기준 1NTU, 수돗물은 0.5NTU. 정수장은 수도법 시행규칙 별표 5의3이 별도 기준(0.3NTU)을 둔다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-070', '잔류염소(유리잔류염소를 말한다)', 'Residual Chlorine (Free)', '-', '㎎/L', '일반', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1(제2조 관련) 제4호 가목', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '괄호 정의문까지가 법령상 항목명이다. 상한 4.0㎎/L는 이 규칙, 하한 0.1㎎/L는 수도법 시행규칙 제22조의2제1항제3호 — ''수돗물 0.1~4.0''은 단일 조문이 아니라 두 규칙의 합성이다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-071', '일반세균', 'Heterotrophic Plate Count', '-', 'CFU/mL', '미생물', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1(제2조 관련) 제1호 가목', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '기준 100CFU/mL. 샘물·염지하수는 저온일반세균/중온일반세균으로 나뉜다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-072', '과망간산칼륨 소비량', 'Potassium Permanganate Consumption', '-', '㎎/L', '유기물', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1(제2조 관련) 제5호 나목', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '기준 10㎎/L. 법령 표기에 공백이 있다(''과망간산칼륨 소비량'')');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-073', '투명도', 'Transparency', '-', 'm', '일반', '수질오염공정시험기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'draft', NULL, '국립환경과학원 API 명세는 단위를 ㎎/L로 적어 두었으나 실제로는 길이 단위 — 명세 오류로 보임');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-075', '유량', 'Flow Rate', '-', '㎥/s', '수문', '물환경보전법 제38조의2 및 수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시)', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '별표 13의 수질오염물질은 아니나 폐수 TMS 의무 전송 6항목 중 하나. 별지 제18호서식 11번 ''수질자동측정기기 등의 측정항목별 점검내용''에 ''유량계''로 등장한다. 2026-08-10 하천 기준으로 근거 없음 판정해 삭제했다가 폐수 원전 확인 후 복구');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-076', '헥사클로로벤젠', 'Hexachlorobenzene', 'HCB', '㎎/L', '유해물질', '환경정책기본법 시행령 별표 1 환경기준(제2조 관련) — 하천 사람의 건강보호 기준', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '별표 13 배출허용기준에는 없고 환경기준(사람의 건강보호)에 있는 항목. 국립환경과학원 API의 itemHcb가 여기에 대응한다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-077', '폐수발생량', 'Wastewater Generation', '-', '㎥/일', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제3호 우측 표 항목 행 ''폐수발생량''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '제18호서식·제20호서식 양쪽에 완전히 같은 표기로 나오는 유일한 수량 항목이라 근거가 가장 강하다. 단위가 갈린다 — 제18호 표두 ''배 출 량  및 사 용 량(㎥/일)'', 제20호 ''폐수발생량(L)''. 1000배 차이라 적재 전 정규화 필수(엔진 규칙). 제20호서식을 ''소규모용''이라 부르지 말 것 — 원문은 ''시행령 제33조제2호 및 제3호에 따라 폐수를 처리하는 사업자''라고만 한다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-078', '폐수배출량', 'Wastewater Discharge', '-', '㎥/일', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제3호 표제 ''용수 공급원별 사용량과 폐수배출량'' 및 우측 표 항목 행 ''폐수배출량''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '발생량(공정에서 생긴 양)과 배출량(방류구로 나간 양)은 서식이 칸을 따로 둔 별개 값이다. 제20호서식에는 없다. WQ-075 유량(㎥/s, 순시)과 차원이 다르므로 합치지 말 것. ''배출부과금 산정의 기초 수량''이라는 설명은 TMS 고시 제15조에 없다 — 인용 금지');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-079', '냉각수량', 'Cooling Water Volume', '-', '㎥/일', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제3호 우측 표 항목 행 ''냉각수량''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '폐수와 구분해 따로 집계하도록 서식이 칸을 나눠 놓았다. 폐수배출량으로 오분류 주의');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-080', '소모(증발량)', 'Consumption (Evaporation)', '-', '㎥/일', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제3호 우측 표 항목 행 ''소모(증발량)''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '괄호까지 포함한 표기가 서식 원문 그대로다. 컬럼명 정규화 시 괄호 처리 규칙 필요. 물질수지 등식(사용량 = 발생 + 냉각 + 소모 + 재사용 + 생활용수)은 서식에 없는 추론이므로 근거가 아니라 엔진 검증식으로 둔다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-081', '재사용량', 'Reuse Volume', '-', '㎥/일', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제3호 우측 표 항목 행 ''재사용량''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, NULL);
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-082', '생활용수량', 'Domestic Water Volume', '-', '㎥/일', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제3호 우측 표 항목 행 ''생활용수량''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, 'MD-023 용수구분명과 이름이 비슷하나 전혀 다르다 — 이쪽은 수량 값, 저쪽은 구분 코드');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-083', '용수사용량', 'Water Intake', '-', '㎥/일', '수량', '물환경보전법 시행규칙 별지 제20호서식 폐수배출시설 운영일지(개정 2018. 1. 17.) ''용수사용량(L)''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '''용수사용량'' 연속 표기는 제20호서식에만 있다. 제18호서식은 표제 ''용수 공급원별 사용량''과 좌측 표 열 ''사용량(㎥/일)''로 표기가 갈리므로 그쪽은 동의어 근거로만 쓴다. 단위는 제18호(㎥/일)를 표준으로 잡고 제20호(L)를 엔진에서 환산');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-084', '슬러지 발생량', 'Sludge Generation', '-', '㎥', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제4호 표제 ''슬러지의 발생량 및 처리량'' 및 표 ''슬러지발생량(㎥)''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, 'PDF 추출문은 행 라벨과 열이 붙어 ''슬러지발생량(㎥)''로 나온다. 표제어는 제3호 폐수발생량과의 구분을 위해 ''슬러지 발생량''으로 띄우되, 원전 열 표기가 ''발생량(㎥)''임을 여기 남긴다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-085', '슬러지 처리량', 'Sludge Treatment', '-', '㎥', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제4호 표 열 ''처리량(㎥)''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '표제어는 표제+열 조합. ''보관량 = 전일보관 + 발생 - 처리'' 검증식은 서식 원문에 없는 추론이므로 근거가 아니라 엔진 규칙으로 둔다(서식에 전일/금일 칸도 없다)');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-086', '슬러지 보관량', 'Sludge Storage', '-', '㎥', '수량', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제4호 표 열 ''보관량(㎥)''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '표제어는 표제+열 조합. 단 ''보관량''은 표제(''슬러지의 발생량 및 처리량'')에 포함되지 않아 발생량·처리량보다 맥락 근거가 약하다 — 근거는 표 소속뿐이다');
INSERT INTO measurement_terms (code, std_name, name_en, abbr, unit, category, legal_basis, legal_article, legal_effective_from, legal_revision, legal_status, is_toxic_substance, toxic_substance_basis, source_url, review_status, reviewed_by, note) VALUES ('WQ-087', '함수율', 'Water Content', '-', '%', '운전지표', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제4호 표 ''함수율(%)''', '제34조', NULL, '개정 2025. 3. 20.', 'non_statutory', FALSE, NULL, NULL, 'verified', NULL, '단위 %가 서식에 명시된 드문 칸. 서식 각주가 기록 주기까지 규정한다 — ''※ 함수율(%)란은 슬러지를 처리하는 경우 또는 슬러지를 적정하게 관리ㆍ처리할 수 있는 주기(월 1회 등)마다 작성합니다.'' 즉 다른 일일 항목과 기록 주기가 다르다. 측정 대상이 물이 아니라 슬러지이므로 시료 종류를 구분하지 않으면 방류수 항목과 뒤섞인다. ''건조중량 환산에 필수''는 원전에 없는 도메인 지식');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-001', '측정소명', 'Station Name', 'MSRSTN_NM', '명V200', 'text', 'station', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, '소스마다 측정소명/조사지점명/시설명/하천명으로 부른다. 지점 마스터와 대조해 코드로 승격 필요', 'verified', NULL, '공통표준용어 등재(5차 2022-07). 서울시 API의 MSRSTN_NM은 이 표준을 그대로 따른 사례');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-002', '측정소코드', 'Station Code', 'MSRSTN_CD', '코드', 'code', 'station', '공통표준용어 미등재 — 공통표준단어 조합(기관표준용어)', NULL, NULL, '기관마다 코드 체계가 달라 그대로는 조인 불가', 'verified', NULL, '공통표준용어 미등재(용어명·이음동의어 exact 0건, 8차 20251101). 꼬리 ''코드''도 미등재라 차용 경로가 없어 조합으로 간다. 현행 공통표준단어 측정소 MSRSTN(測定所 ''재는 장소'', 5차) + 코드 CD(형식단어, 도메인분류 코드) 조합. 동음이의 없음(측정소·코드 각 1건), 약어 충돌 0건. 자릿수는 기관마다 달라 도메인분류명만 적고 구체 자릿수는 두지 않는다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-003', '하천명', 'River Name', 'RVR_NM', '명V100', 'text', 'station', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, '측정소명과 구분해야 한다. 하천명만 있고 지점이 없는 데이터가 존재', 'verified', NULL, '공통표준용어 등재(5차 2022-07)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-004', '시설명', 'Facility Name', 'FCLT_NM', '명V256', 'text', 'station', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, '정수장·물재생센터·약수터 등 시설 단위 관측의 지점명. 측정소명(MD-001)과 구분', 'verified', NULL, '공통표준용어 등재 확인(8차 20251101, exact match). 영문약어 FCLT_NM, 도메인 명V256. 실데이터 표기 FACLT_NM(경기 수도정보 API)이 이 표준약어와 대응하여 채택. 이음동의어 ''시설이름·시설명칭''도 등재됨. 구 표준명 ''측정시설명''은 동의어로 보존');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-005', '시설번호', 'Facility Number', 'FCLT_NO', '번호V20', 'code', 'station', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, NULL, 'verified', NULL, '공통표준용어 등재 확인(8차 20251101, exact match). 영문약어 FCLT_NO, 도메인 번호V20. 실데이터 표기 FACLT_NO(경기 수도정보 API)가 이 표준약어와 대응하여 채택. 구 표준명 ''측정시설번호''는 동의어로 보존');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-030', '채수지점번호', 'Sampling Spot Number', '-', NULL, 'code', 'station', '공통표준용어 미등재(exact 0건, 8차 20251101) — 지점=支店이라 조합 불가, 개념 동일성 미확인', NULL, NULL, NULL, 'draft', NULL, '공통표준용어 미등재(exact 0건, 8차 20251101). 조합도 불가 — 공통표준단어 ''지점'' BRNCH는 支店(본점에서 갈라져 나온 점포)이라 측정 地點이 아니다(BRNCH_ 접두 현행 7건 전부 상업 점포). 地點 계열은 ''측정지점'' MSPT·''관측지점'' OBSPT로 따로 등재돼 있다. 근접 용어 ''측정지점번호'' MSPT_NO(번호V50)가 있으나 우리 이름의 꼬리가 아니어서 포함관계 차용이 성립하지 않고, 채수 장소와 측정 장소가 같은 실체인지도 원본 정의서 없이는 확인되지 않는다. 2026-08-10 폐수 원전 대조 결과 미해결 확정 — ''채수지점'' 0건. 폐수에서 이 자리를 차지하는 실체는 ''방류구''이나 개념이 달라 재정의가 아니라 신규 등재로 처리했다(MD-033). 이 코드에는 경기 약수터 SPOT_NO가 바인딩돼 있어 개명하면 약수터 채수지점이 폐수 방류구에 묶인다. 적용범위를 하천·약수터로 한정한다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-006', '측정일자', 'Measurement Date', 'MSRMT_YMD', '연월일C8', 'date', 'time', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'YYYY-MM-DD', '실데이터 포맷이 2012.02.03 / 20260805 / 2021-04-11로 제각각 — 적재 시 통일', 'verified', NULL, '공통표준용어 등재(3차 2021-10). 저장 YYYYMMDD / 표현 YYYY-MM-DD');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-007', '측정일시', 'Measurement Datetime', 'MSRMT_DT', '연월일시분초D', 'timestamp', 'time', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'YYYY-MM-DD HH24:MI:SS', '날짜와 시각이 분리된 소스는 결합해서 채운다', 'verified', NULL, '공통표준용어 등재(4차 2021-12)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-008', '측정연도', 'Measurement Year', 'MSRMT_YR', '연도C4', 'integer', 'time', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'YYYY', '연/월을 분리 저장하는 소스가 많다. 측정일자로 통합 가능하면 통합', 'verified', NULL, '공통표준용어 등재 확인(8차 20251101, exact match). 설명: 일정한 양을 기준으로 하여 같은 종류의 다른 양의 크기를 잰 연도');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-009', '측정월', 'Measurement Month', 'MSRMT_MM', '월C2', 'integer', 'time', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'MM', '''02''처럼 zero-pad 문자열로 오는 소스 있음', 'verified', NULL, '공통표준용어 등재 확인(8차 20251101, exact match). 설명: 기계나 장치를 사용하여 일정한 양을 기준으로 같은 종류의 다른 양의 크기를 잰 월');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-010', '측정회차', 'Measurement Round', '-', NULL, 'text', 'time', '공통표준용어 미등재(exact 0건, 8차 20251101) — 서수/개수 미확인으로 후보 2택 미결', NULL, NULL, '값 미확보(NIER API ServiceKey 필요). 저장소에 값 스냅샷이 없다', 'draft', NULL, '공통표준용어 미등재(용어명·이음동의어 exact 0건, 8차 20251101). ''회차''는 공통표준단어 단독 등재 0건이라 조합도 불가. 근접 후보 ''측정차수'' MSRMT_CYCL과 ''측정횟수'' MSRMT_NMTM이 둘 다 수N10·7차(2024-11) 현행으로 병존해, 값이 서수(n번째 측정)인지 개수(총 몇 회)인지 모르면 확정할 수 없다. 표준은 회차→차수 매핑을 제공하지 않는다(이음동의어 0건). 2026-08-10 폐수 원전 대조 결과 미해결 확정 — 별지 제18·20호서식과 수질원격감시체계 관제센터 운영 등에 관한 규정에 ''회차·차수·횟수·순번'' 0건. 제18호서식 제1·2호의 1~24는 하루의 시간대이고 제3호의 1호·2호는 계량기 호수다. TMS의 5분 자료·시간 자료·24시간 평균치는 집계 주기이지 순번이 아니다. 적용범위를 하천·먹는물 정기검사로 한정한다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-011', '시료채취일자', 'Sampling Date', 'SPCM_PCKNG_YMD', '연월일C8', 'date', 'time', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'YYYY-MM-DD', '측정일자(MD-006)와 개념이 다를 수 있다(채수일 vs 분석일) — 소스별 정의 확인 필요', 'verified', NULL, '공통표준용어 등재(7차 2024-11). 별도로 ''채수일자'' WTSMP_YMD도 등재돼 있어 어느 쪽을 쓸지 팀 규칙이 필요하다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-012', '측정시각', 'Measurement Time', 'MSRMT_TM', '시분초C6', 'text', 'time', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'HH24:MI', NULL, 'verified', NULL, '공통표준용어 등재 확인(8차 20251101, exact match). 설명: 기계나 장치를 사용하여 일정한 양을 기준으로 같은 종류의 다른 양의 크기를 재는 어느 한 시점');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-013', '위도', 'Latitude', 'LAT', '위도N12,10', 'numeric', 'space', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'WGS84 십진도', '국립환경과학원은 도/분/초 3개 필드로 분리 제공(latDgr/latMin/latSec) — 십진도 환산 필요', 'verified', NULL, '공통표준용어 등재(2차 2020-12), 소관 국토교통부. 표현형식 99.9999999999');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-014', '경도', 'Longitude', 'LOT', '경도N13,10', 'numeric', 'space', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'WGS84 십진도', '동일하게 lonDgr/lonMin/lonSec 분리 제공', 'verified', NULL, '공통표준용어 등재(2차 2020-12), 소관 국토교통부. 표준 약어가 LNG/LON이 아니라 LOT다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-015', '소재지주소', 'Address', 'LCTN_ADDR', '주소V200', 'text', 'space', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, NULL, 'verified', NULL, '공통표준용어 등재(4차 2021-12)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-016', '도로명주소', 'Road Name Address', 'ROAD_NM_ADDR', '주소V200', 'text', 'space', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, NULL, 'verified', NULL, '공통표준용어 등재(2차 2020-12), 소관 행정안전부. 상세 주소는 제외한다고 명시됨');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-017', '시도명', 'Province Name', 'CTPV_NM', '명V40', 'text', 'space', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, '''전라북도''처럼 개편 전 명칭이 데이터에 남아 있다(현 전북특별자치도)', 'verified', NULL, '공통표준용어 등재(2차 2020-12). 단어 시도=CTPV(Cities And Provinces)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-018', '시군구명', 'District Name', 'SGG_NM', '명V40', 'text', 'space', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, NULL, 'verified', NULL, '공통표준용어 등재(2차 2020-12)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-019', '법정동시군구코드', 'Legal District Code', 'STDG_SGG_CD', '코드C3', 'code', 'space', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', '3자리', '법정동코드 10자리 중 3~5번째 자리(110:종로구, 140:중구). 10자리 전체가 필요하면 ''법정동코드'' STDG_CD(코드C10)를 쓴다', 'verified', NULL, '''시군구코드''는 공통표준용어에 없다(0건). 표준 명칭은 ''법정동시군구코드''이므로 표준명을 그쪽으로 맞췄다. 소관 국토교통부');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-020', '읍면동명', 'Town Name', 'EMD_NM', '명', 'text', 'space', '공통표준용어 미등재 — 공통표준단어 조합(기관표준용어)', NULL, NULL, '전북 값 62종 중 ''가'' 표기 6종(다가동3가 등), 숫자형 행정동(평화1동 류) 0종. 읍/면 9,695행 중 9,191행에 리가 채워지고 동·가 3,150행은 리 공란 — 다만 읍인데 리가 전무한 504행(운봉읍·삼례읍·신태인읍)이 있어 계층 근거로는 불충분', 'verified', NULL, '공통표준용어 미등재(용어명·이음동의어 exact 0건, 8차 20251101). 꼬리 ''명''·''동명''·''면동명'' 모두 미등재라 차용 경로가 없어 조합으로 간다. 현행 공통표준단어 읍면동 EMD(邑面洞 ''행정 구역 단위인 읍·면·동을 아울러 이르는 말'', 2차) + 명 NM(형식단어) 조합. 동음이의 없음(읍면동 1건), 약어 충돌 0건. 표준 자신도 무수식 읍면동+명을 ''영문읍면동명'' ENG_EMD_NM(명V40, 현행)으로 쓴다. 법정동/행정동 구분은 값의 의미 문제라 이름 판정을 막지 않는다 — norm 참조');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-021', '리명', 'Village Name', 'LI_NM', '명', 'text', 'space', '공통표준용어 미등재 — 공통표준단어 조합(기관표준용어)', NULL, NULL, '전북 원본 컬럼명은 ''동리 명''이고 비공백 고유값 53종이 전부 ''리''로 끝난다', 'verified', NULL, '공통표준용어 미등재(용어명·이음동의어 exact 0건, 8차 20251101. ''행정리명''도 0건). 꼬리 ''명''·''리명'' 모두 미등재라 차용 경로가 없어 조합으로 간다. 현행 공통표준단어 리 LI(里 ''지방 행정의 말단 구역. 읍과 면의 아래에 둔다'', 5차) + 명 NM(형식단어) 조합. 동음이의 없음, 약어 충돌 0건. 종전 ''법정리명'' STLI_NM은 폐기, 현행은 ''법정동리명'' STDG_LI_NM(명V100)이나 이는 우리 이름보다 좁은 하위 개념이라 차용 대상이 아니다. MD-020과 동일 판정');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-022', '기관명', 'Institution Name', 'INST_NM', '명V200', 'text', 'organization', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, NULL, 'verified', NULL, '공통표준용어 등재(2차 2020-12). 코드가 필요하면 ''기관코드'' INST_CD(코드C7). 초안의 ''측정기관명''은 표준 명칭이 아니라 ''기관명''이다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-023', '용수구분명', 'Water Use Type', '-', NULL, 'text', 'sampling', '공통표준용어 ''구분명'' 차용', NULL, NULL, NULL, 'verified', NULL, '공통표준용어 미등재(용어명·이음동의어 exact 0건, 8차 20251101). 포함관계 상위어 ''구분명'' SE_NM(명V100, 5차 2022-07)에서 개념을 차용. ''용수''라는 수식어가 무엇의 구분인지를 담고 있어 ''구분명''으로 개명하면 의미가 손실되므로 이름은 유지한다. abbr은 비운다 — 수식어가 붙은 표준용어는 기저 약어를 그대로 쓰지 않는다(수식어+등재용어 6,453쌍 전수 대조 결과 재사용 0건. 예: 용도구분명 USG_SE_NM). domain도 비운다 — 경기 API 실호출 응답값을 확보하지 못해 명V100 사양 충족을 확인할 수 없다(''~구분명'' 69건 중 명V100은 60건으로 계열 내에서도 확정적이지 않다)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-024', '채수수심', 'Sampling Depth', '-', NULL, 'numeric', 'sampling', '공통표준용어 미등재(exact 0건, 8차 20251101) — 말미 형식단어(수심/깊이) 미확정', NULL, NULL, '국립환경과학원 wmdep. 같은 지점 다른 수심의 값이 별도 행으로 오면 수심을 복합키에 포함해야 덮어쓰기가 나지 않는다. 단위 m는 명세에서 확인하지 못한 가정이라 뺐다. 값 미확보', 'draft', NULL, '공통표준용어 미등재(exact 0건, 8차 20251101) — 말미 형식단어 미확정: ''수심'' WTDPT는 水深 ''강이나 바다, 호수 따위의 물의 깊이''로 수체 자체의 깊이를 뜻하고(유일 용례 평균수심 AVG_WTDPT도 그렇다), 우리 개념은 시료를 뜬 위치의 깊이다. 표준의 행위어+깊이 관용은 ''깊이'' DPTH(굴착깊이 EXCV_DPTH 등)이고 採水 설명 자신이 ''서로 다른 깊이의 물을 떠올리는 일''이라 쓴다. 채수 WTSMP는 확정이나 꼬리 단어를 정해야 조합이 성립한다. 2026-08-10 폐수 원전 대조 결과 미해결 확정 — ''수심·깊이·채수'' 각 0건. 나아가 폐수는 수심 방향으로 층이 진 수체가 아니라 방류구와 조에서 채취한다(제18호서식 제11호가 시료 경로를 ''시료채취조 → 시료도입[튜빙(tubing: 배관)류]''로 규정). 폐수 도메인 적용 제외');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-025', '측정결과적합여부', 'Compliance Result', '-', NULL, 'boolean', 'quality', '공통표준용어 ''적합여부'' 차용', NULL, NULL, '부산 약수터 ''검사결과''에서 ''적합''/''부적합'' 2값 관측. 표준 ''적합여부''의 도메인 여부C1은 ''Y : 여(예), N : 부(아니요)'' 1자리이므로 적재 시 변환이 필요하다. 경기 MESURE_RESLT_SUITBLT_YN의 실제 값은 미확인', 'verified', NULL, '공통표준용어 미등재(용어명·이음동의어 exact 0건, 8차 20251101). 포함관계 상위어 ''적합여부'' STBLT_YN(여부C1, 1차 2020-08)에서 개념을 차용. ''측정결과''라는 수식어가 무엇의 적합인지를 담고 있어 이름은 유지한다. abbr은 비운다 — 표준 자신이 수식어가 붙으면 약어를 확장한다(위생상태적합여부 SNTT_STTS_STBLT_YN). domain도 비운다 — 관측값이 여부C1 사양을 위반하므로 변환 규칙 확정 전에는 채우지 않는다. 검사여부(MD-031)와 같은 형태');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-026', '초과오염물질', 'Exceeded Pollutant', '-', NULL, 'text', 'quality', '수질원격감시체계 관제센터 운영 등에 관한 규정 제5조제3호나목', NULL, NULL, '기준을 초과한 오염물질을 담는다 — 측정항목 사전(WQ-*)과 대조해 파싱 가능. 경기 EXCESS_ITEM_NM의 실제 응답값은 여전히 미확보라 한 건만 담는지 구분자로 여러 건을 묶는지 모른다(이 미결은 표제어 교체로 해소되지 않는다 — 고시는 관제센터 저장 구조를 규정할 뿐 경기 API의 값 카디널리티를 정해 주지 않는다)', 'verified', NULL, '2026-08-10 표제어 교체. 구 표제어 ''초과항목명''은 두 폐수 원전에 0건인 창작 표기였다. 근거: 수질원격감시체계 관제센터 운영 등에 관한 규정 제5조제3호나목 — ''배출허용기준등을 초과한 자료의 사업장별, 방류구별 초과오염물질·초과농도·초과시간 및 초과량 저장''. 같은 목이 초과 사실을 4개 필드로 분해하므로 이 용어는 단독이 아니라 MD-052 초과농도·MD-046 초과시간·MD-053 초과량과 한 세트로 쓴다. 적용범위 주의 — 경기 약수터 EXCESS_ITEM_NM에 이 용어를 붙일 때 초과 기준은 배출허용기준이 아니라 먹는물 수질기준이며, 초과 대상이 ''오염물질''이 아닌 항목(탁도 등)일 수 있다. 행정안전부 공통표준용어에는 여전히 미등재(exact 0건, 8차 20251101)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-031', '검사여부', 'Inspection Performed', 'INSP_YN', '여부C1', 'boolean', 'quality', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', NULL, '''검사''/''미검사'' 2값. 측정 실시 자체의 여부이며 결과 적합여부(MD-025)와 다르다', 'verified', NULL, '공통표준용어 등재 확인(8차 20251101, exact match). 설명: 사실이나 일의 상태 또는 물질의 구성 성분 따위를 조사하여 옳고 그름과 낫고 못함을 판단하는 일을 실시했는지 여부');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-032', '미검사사유', 'Non-Inspection Reason', '-', NULL, 'text', 'quality', '공통표준용어·표준단어 미등재 — 소스 관행', NULL, NULL, '자유 서술 텍스트. 코드화되어 있지 않다', 'draft', NULL, '검사여부(MD-031)가 미검사일 때만 채워진다. 부산 약수터 데이터에서 확인. 공통표준용어 미등재(exact 0건, 8차 20251101). 공통표준단어 ''미''·''미검사'' 모두 미등재라 조합 불가 — 표준은 未+행위를 단일 단어로 등재한다(미사용 UNSD, 미납 UNPAID, 미결 PND). 근접 용어 ''미사용사유'' UNSD_RSN(내용V4000)은 개념이 다르다. 표준 미비로 해소 불가. 2026-08-10 폐수 원전 대조 결과 미해결 확정 — ''미검사'' 0건, 별지 서식에는 ''사유·검사'' 자체가 0건. TMS 고시의 ''개선사유''(제5조제9호·제9조제5항)와 제12조제3항 무효사유는 모두 ''기기는 돌았으나 값을 믿을 수 없는'' 경우이지 ''검사를 하지 않은'' 경우가 아니다. 합치면 무효자료와 미실시가 섞인다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-029', '자료기준일자', 'Data Reference Date', 'DATA_CRTR_YMD', '연월일C8', 'date', 'record', '공공데이터 공통표준용어(행정안전부, 20251101 8차)', 'https://www.data.go.kr/data/15156379/fileData.do', 'YYYY-MM-DD', '관측일이 아니라 파일 갱신일이다. 측정일자(MD-006)와 절대 혼동하면 안 된다', 'verified', NULL, '''데이터기준일자''는 공통표준용어에 없다(0건). ''데이터''는 공통표준단어에도 없고 ''자료''=DATA가 정식이므로 표준명을 ''자료기준일자''로 맞췄다. 실데이터 컬럼은 ''데이터기준일자''로 오므로 동의어로 등록');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-033', '방류구', 'Discharge Outlet', '-', NULL, 'text', 'station', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제5조제4호나목·다목·마목', NULL, NULL, '폐수 자료의 지점 그레인 그 자체. 한 사업장에 여럿 존재하고 방류구마다 측정항목과 배출허용기준이 따로 설정된다. 이 축이 없으면 방류구별 배출현황·기준·초과자료가 사업장 단위로 뭉개져 덮어쓰기가 난다. value_type을 code가 아니라 text로 둔다 — ''방류구번호''·''방류구코드'' 표기는 두 원전 grep 0건이라 식별자 형식을 정할 근거가 없다', 'verified', NULL, '근거 5곳: 제5조제2호가목 ''사업장별, 방류구별, 오염물질별 배출현황'' / 제3호나목 ''사업장별, 방류구별 초과오염물질…'' / 제4호나목 ''방류구 관리에 필요한 기초사항'' / 다목 ''방류구별 측정항목'' / 마목 ''방류구별, 오염물질별 배출허용기준등 설정 및 관리''. 별지 제18호서식에는 ''방류구''가 0건이고 제10호의 ''방류수''는 시료의 종류이지 지점 식별자가 아니므로 근거로 쓰면 안 된다. MD-030 채수지점번호와는 별개 실체다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-034', '사업장 명칭', 'Business Site Name', '-', NULL, 'text', 'station', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제13조의2제1항', NULL, NULL, '폐수 데이터의 최상위 집계 단위. 고시가 배출현황·부과금 산정·초과자료·공개자료를 모두 ''사업장별''로 규정한다. 사업장 식별 ''코드/번호''에 해당하는 표현은 두 원전 어디에도 없어 코드 용어는 만들지 않았다', 'verified', NULL, '제13조의2제1항 ''사업장별 명칭 및 소재지, 시설용량 등 일반 현황''. 원전 표기가 ''사업장별 명칭''이므로 표제어를 ''사업장 명칭''으로 두었다(''사업장'' 단독은 개체명이지 컬럼명이 아니다). 같은 축의 다른 표기 병존 — 제5조제10호 ''측정기기부착사업장'', 제5조제9호 ''측정기기부착사업자등''(사업자). 별도 행으로 세우지 않고 여기 기록한다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-035', '처리방법', 'Treatment Method', '-', NULL, 'text', 'station', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제2호', NULL, NULL, '방지시설의 처리 공법. 값 도메인이 서식에 열거돼 있지 않으므로 자유 텍스트로 둔다', 'verified', NULL, '별지 제18호서식 제2호 ''수질오염방지시설 가동시간대(처리방법:                           )'' 표제 괄호 안 기입란. 제8호가 ''(생물화학적 처리시설의 경우)''로 한정되므로 이 값이 어떤 운전지표 칸이 채워져야 정상인지를 결정한다 — 조건부 기재 규칙의 입력. facet은 시료 채취 맥락이 아니라 시설 속성이므로 sampling이 아닌 station');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-039', '폐수배출시설 가동(조업)시간대', 'Discharge Facility Operating Hours', '-', NULL, 'text', 'time', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제1호', NULL, NULL, '1시간 단위 24칸 on/off 격자다. 스칼라 시각값인 MD-012 측정시각으로는 표현할 수 없어 24비트 벡터 자료형 정의가 함께 필요하다(사전에 선례 없음)', 'verified', NULL, '별지 제18호서식 제1호 표제 ''폐수배출시설 가동(조업)시간대'' 및 표 머리 ''시간대/구분''과 값 칸 1~24. 서식 말미 주석상 필수 기재 구간(제1~4호). ''※ 시간대 표시는 검은색''은 제1호가 아니라 제2호 격자 뒤에 붙어 있다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-040', '수질오염방지시설 가동시간대', 'Prevention Facility Operating Hours', '-', NULL, 'text', 'time', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제2호', NULL, NULL, '제1호와 별도의 24칸 격자. 두 격자를 하나로 접으면 배출시설과 방지시설의 시간대가 뭉개진다', 'verified', NULL, '별지 제18호서식 제2호 표제 ''수질오염방지시설 가동시간대(처리방법:  )'' 및 값 칸 1~24. 필수 기재 구간. 배출시설은 가동 중인데 방지시설이 정지한 시간대가 위반 신호라는 것은 원전에 없는 활용 해석이므로 엔진 규칙으로 둔다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-041', '분석일', 'Analysis Date', '-', NULL, 'date', 'time', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제10호', NULL, 'YYYY-MM-DD', '시료를 채취한 날과 분석한 날이 다를 수 있다. 주의 — MD-006 측정일자의 동의어에 이미 ''검사일자''가 있어 의미가 상당 부분 겹친다. 자가측정 데이터에서 분석일과 측정일자를 가르는 규칙을 정하지 않으면 중복 매핑이 난다', 'verified', NULL, '별지 제18호서식 제10호 ''수질오염물질 측정내용'' 항목 열 마지막. ''시료 보관시간 초과 판정에 필요''는 원문 밖 해석');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-046', '초과시간', 'Exceedance Duration', '-', NULL, 'text', 'time', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제5조제3호나목', NULL, NULL, '초과가 지속된 시간. MD-007 측정일시(시점)와 다른 구간 개념이라 별도 용어가 필요하다. 고시가 지속시간인지 초과 시각인지 정의하지 않아 자료형을 numeric으로 확정하지 않았다', 'verified', NULL, '제5조제3호나목이 저장하도록 규정한 초과 4요소 중 하나 — ''초과오염물질·초과농도·초과시간 및 초과량''. MD-026·MD-052·MD-053과 한 세트. ''배출부과금 산정의 직접 입력값(제5조제2호마목·제15조)''이라는 보강 근거는 원전에 없다 — 제5조제2호마목은 ''사업장별 배출부과금 부과자료 산정'', 제15조제1항은 부과금의 구성만 규정할 뿐 초과시간과의 연결이 어디에도 없다. 이 문장을 근거로 쓰지 말 것');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-050', '측정방법', 'Measurement Method', '-', NULL, 'text', 'sampling', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제5조제4호라목', NULL, NULL, '같은 항목이라도 연속자동측정과 수(手)분석은 값의 성격이 다르다. 다만 값 도메인 2종을 원전이 열거한 것은 아니므로 코드값을 임의로 정하지 말 것', 'verified', NULL, '제5조제4호라목 ''부착된 측정기기별 특성 및 측정방법''. 보강 — 제2조제2호나목 상대정확도시험이 ''연속자동측정방법 측정값과 항목별 주 시험방법 수(手)분석값 간 오차율 비교''로 정의돼 두 계열이 구분되는 실체임을 뒷받침한다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-052', '초과농도', 'Exceedance Concentration', '-', NULL, 'numeric', 'quality', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제5조제3호나목', NULL, NULL, '초과 4요소 중 하나. 주의 — 원전은 나열만 할 뿐 이 값이 (측정농도 − 기준값)인지 초과 당시의 측정농도인지 정의하지 않는다. 이 추론을 정의란에 근거처럼 쓰지 말 것. 참고로 ''측정농도''는 제5조제5호에 별도로 존재한다', 'verified', NULL, '제5조제3호나목 ''초과오염물질·초과농도·초과시간 및 초과량''. 물리량이지만 개별 측정 칸이 아니라 고시가 저장 대상으로 규정한 산출값이라 측정항목이 아니라 메타에 둔다(이 사전의 분류 규칙 예외 조항)');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-053', '초과량', 'Exceedance Load', '-', NULL, 'numeric', 'quality', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제5조제3호나목', NULL, NULL, '초과 4요소 중 하나. ''초과농도 × 유량으로 산출된다''와 ''초과배출부과금의 과표다''는 두 원전 어디에도 없는 창작이므로 근거로 쓰지 말 것 — 제15조제1항은 부과금이 기본+초과로 구성된다고만 하고 과표를 규정하지 않는다', 'verified', NULL, '제5조제3호나목이 저장하도록 규정한 4개 필드 중 하나');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-054', '배출허용기준', 'Effluent Limit', '-', NULL, 'numeric', 'quality', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제5조제4호마목', NULL, NULL, '폐수 데이터의 판정 기준값. MD-025 측정결과적합여부는 적합/부적합 결과만 담고 무엇에 견주었는지를 담지 못한다. 고시가 기준값을 방류구별·오염물질별로 ''설정 및 관리''하는 저장 대상으로 명시하므로 기준값 자체가 데이터 항목이다', 'verified', NULL, '제5조제4호마목 ''방류구별, 오염물질별 배출허용기준등 설정 및 관리'', 제13조제3항. 표기 주의 — 제5조 계열은 전부 ''배출허용기준등''(등 포함)이고 ''등'' 없는 표기는 제13조제3항뿐이다. 표제어는 ''등'' 없는 쪽을 채택하고 ''배출허용기준등''을 동의어로 둔다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-055', '방류수수질기준', 'Effluent Quality Standard', '-', NULL, 'numeric', 'quality', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제13조제3항', NULL, NULL, '배출허용기준과 병렬로 쓰이는 별개의 법정 기준(공공폐수처리시설 계열). 한 컬럼으로 뭉치면 어느 기준으로 초과 판정됐는지 추적이 끊긴다. 주의 — MD-033과 별개로 별지 제18호서식 제10호의 값 ''방류수''와 문자열이 겹치므로 사전 검색 시 충돌 방지 필요', 'verified', NULL, '제13조제3항 ''24시간 평균치가 방류수수질기준 또는 배출허용기준 초과 시 15일 이내 확정 통보''. tms.md는 발췌본이라 관보 원문의 띄어쓰기(''방류수 수질기준'' 여부)는 재확인 필요');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-066', '측정대행업소명', 'Measurement Agency Name', '-', NULL, 'text', 'organization', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제10호', NULL, NULL, '타깃 사용자(폐수측정 업체) 자신이 기재되는 칸이다. 현재 organization 축은 MD-022 기관명 하나뿐이라 역할이 다른 업체들이 전부 한 칸에 뭉개진다. MD-068 위탁처리업소명(슬러지)·MD-069 처리업소명(폐수)과 반드시 구분할 것', 'verified', NULL, '별지 제18호서식 제10호 아래 ''※ 분석을 위탁하는 경우 측정대행업소명:''');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-067', '분석자명', 'Analyst Name', '-', NULL, 'text', 'organization', '물환경보전법 시행규칙 별지 제18호서식 폐수배출시설 및 수질오염방지시설 운영일지(개정 2024. 11. 7.) 제10호', NULL, NULL, '자가분석 시의 책임자. MD-066과 배타적으로 채워지는 짝 칸이라 함께 등재해야 자가/위탁 두 경로가 구분된다. 개인 성명 필드이므로 공개 데이터셋에서는 비식별 대상일 수 있다', 'verified', NULL, '별지 제18호서식 제10호 아래 ''※ 사업장에서 분석하는 경우 분석자명:''');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-072', '24시간 평균치', '24-Hour Average', '-', NULL, 'numeric', 'record', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제13조제1항', NULL, NULL, '초과 판정이 개별 측정값이 아니라 이 값으로 이뤄진다. 고시가 따옴표로 정의어를 부여한 정식 용어다. 5분·시간·24시간으로 층이 나뉘는 자료 주기 자체는 컬럼이 아니라 값이므로 엔진의 코드값 세트로 둔다(원전에 주기 구분 컬럼명이 없다)', 'verified', NULL, '제13조제1항 ''행정자료 활용을 위해 "24시간 평균치" 생성'', 제13조제3항. 생성방법은 별표3이며 별표3은 확보 범위 밖이다');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-073', '일일 평균 농도', 'Daily Average Concentration', '-', NULL, 'numeric', 'record', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제13조의2제1항', NULL, NULL, '대국민 공개 자료의 법정 항목. 폐수 업체가 실제로 마주하는 공개 데이터셋의 컬럼 이름이 이것이므로 사전에 없으면 공개 데이터 매핑이 바로 실패한다. MD-072 24시간 평균치와 같은 값인지 다른 값인지는 고시가 정의하지 않으므로 동일시하지 말 것', 'verified', NULL, '제13조의2제1항 ''수질오염물질 일일 평균 농도 및 일일 배출량''');
INSERT INTO metadata_terms (code, std_name, name_en, abbr, std_domain, value_type, facet, standard_basis, source_url, canonical_format, normalization_note, review_status, reviewed_by, note) VALUES ('MD-074', '일일 배출량', 'Daily Discharge Load', '-', NULL, 'numeric', 'record', '수질원격감시체계 관제센터 운영 등에 관한 규정(환경부고시) 제13조의2제1항', NULL, NULL, '농도와 구분되는 부하량 축. WQ-078 폐수배출량(수량, ㎥/일)·WQ-075 유량(㎥/s)과 차원이 다르므로 세 개념의 경계를 지켜야 중복 등록을 피한다', 'verified', NULL, '제13조의2제1항');
