INSERT INTO term_synonyms (measurement_code, metadata_code, surface, source_id, collected_on, evidence_url, evidence_snippet, synonym_type, review_status, note) VALUES ('WQ-063', NULL, '대장균·분원성 대장균군', 'LAW_DRINKING', '2026-08-05', 'https://www.law.go.kr/LSW/flDownload.do?flSeq=158952499', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1 제1호 다목', 'legal_variant', 'verified', '먹는물 기준은 대장균과 분원성대장균군을 한 항목으로 묶는다 — 1:1 매핑이 성립하지 않는 사례');
