INSERT INTO term_synonyms (measurement_code, metadata_code, surface, source_id, collected_on, evidence_url, evidence_snippet, synonym_type, review_status, note) VALUES ('WQ-027', NULL, '불소', 'LAW_DRINKING', '2026-08-05', 'https://www.law.go.kr/LSW/flDownload.do?flSeq=158952499', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1 제2호 나목', 'legal_variant', 'verified', '먹는물 기준의 법령 표기는 ''불소''(1.5㎎/L). 별표 13은 ''플로오르(불소)함유량'' — 초안이 동의어로 넣었던 ''불소''는 실제 법령 표기였다');
INSERT INTO term_synonyms (measurement_code, metadata_code, surface, source_id, collected_on, evidence_url, evidence_snippet, synonym_type, review_status, note) VALUES ('WQ-056', NULL, '크실렌', 'LAW_DRINKING', '2026-08-05', 'https://www.law.go.kr/LSW/flDownload.do?flSeq=158952499', '먹는물 수질기준 및 검사 등에 관한 규칙 별표 1 제3호 머목', 'legal_variant', 'verified', '먹는물 기준은 ''크실렌'', 별표 13은 ''자일렌''. 같은 물질(Xylene)의 두 법령 표기');
