INSERT INTO term_synonyms (measurement_code, metadata_code, surface, source_id, collected_on, evidence_url, evidence_snippet, synonym_type, review_status, note) VALUES ('WQ-070', NULL, '유리잔류염소', 'LAW_WATERWORKS', '2026-08-05', 'https://www.law.go.kr/법령/수도법시행규칙', '수도법 시행규칙 제22조의2제1항제3호: ''수도꼭지의 먹는물 유리잔류염소가 항상 0.1밀리그램/리터(결합잔류염소는 0.4밀리그램/리터) 이상이 되도록 할 것''', 'legal_variant', 'verified', '하한 기준 조문. 단위를 ''㎎/L''가 아니라 한글 ''밀리그램/리터''로 적는다');
INSERT INTO term_synonyms (measurement_code, metadata_code, surface, source_id, collected_on, evidence_url, evidence_snippet, synonym_type, review_status, note) VALUES ('WQ-070', NULL, '잔류염소', 'LAW_WATERWORKS', '2026-08-05', 'https://www.law.go.kr/법령/수도법시행규칙', '수도법 시행규칙 제22조의4제3항제1호: ''잔류염소: 리터당 0.1밀리그램 이상 4.0밀리그램 이하''', 'legal_variant', 'verified', '저수조 청소 후 점검 기준. 여기서는 괄호 정의문 없이 ''잔류염소''로만 쓴다');
